(()=>{
 const en=document.documentElement.lang==='en',t=(a,b)=>en?b:a,$=id=>document.getElementById(id);
 const hero=document.querySelector('.hero');hero.querySelector('h1').textContent=t('从下一节课，规划完整到达过程。','Next class. Complete journey.');hero.querySelector('.lede').textContent=t('课程时间 → 校外公交／火车 → 校门与建筑 → 楼层和教室。把分散信息放在一个流程中。','Class time → bus or train → campus entrance → building and classroom. Keep the information together.');hero.querySelector('aside h2').textContent=t('目的地是教室，不只是车站','The classroom, beyond the station');
 const panel=document.createElement('section');panel.id='classes';panel.className='planner';panel.innerHTML=`<p class="eyebrow">01 / NEXT CLASS</p><h2>${t('我的课程与到达计划','My classes and arrival plan')}</h2><p>${t('手动添加课程；不会连接学校账户。示例课程仅用于演示。默认只存于本页内存，可自行选择保存到本机浏览器。','Add a class manually; no university account connection. Sample classes are fictional. Entries stay in page memory unless local browser storage is selected.')}</p><div class="plan-grid"><form id="classForm" class="route-card"><label>${t('课程名称','Class title')}<input id="courseTitle" maxlength="80" required placeholder="${t('例如 HCI seminar','e.g. HCI seminar')}"></label><div class="two-col"><label>${t('日期（英国时间）','Date (UK time)')}<input id="courseDay" type="date" required></label><label>${t('开始时间','Start time')}<input id="courseTime" type="time" value="10:00" required></label></div><label>${t('教学楼','Building')}<select id="courseBuilding"></select></label><div class="two-col"><label>${t('教室编号（可留空）','Room code (optional)')}<input id="courseRoom" maxlength="50" placeholder="${t('按课表原样输入','Copy from timetable')}"></label><label>${t('楼层（如已知）','Floor (if known)')}<input id="courseFloor" maxlength="50"></label></div><label>${t('入口／找教室备注（用户填写，未核验）','Entrance / room notes (user supplied, unverified)')}<textarea id="courseNotes" rows="3" maxlength="400" style="width:100%;font:inherit"></textarea></label><label><input type="checkbox" id="saveClasses" style="width:auto"> ${t('保存课程到此浏览器（共享设备请勿勾选）','Save classes on this browser (avoid shared devices)')}</label><button class="primary">${t('添加课程','Add class')}</button></form><div class="route-card"><h3>${t('课程列表','Class list')}</h3><p id="classStatus" role="status"></p><div id="classList"></div><button class="outline" id="sampleClass">${t('添加一条虚构示例','Add a fictional sample')}</button> <button class="outline" id="clearClasses">${t('清空课程和本地保存','Clear classes and local copy')}</button></div></div><section class="recommendation" style="margin-top:24px"><h3>${t('完整到达计划','Complete arrival plan')}</h3><div id="classJourney" aria-live="polite"></div></section></section>`;hero.after(panel);
 $('courseBuilding').innerHTML=$('building').innerHTML;$('courseDay').value=$('commuteDate').value;
 let courses=[],selected=null;const key='greengo-classes-v1';
 function valid(c){return c&&typeof c.id==='string'&&typeof c.title==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(c.day)&&/^\d{2}:\d{2}$/.test(c.time)&&Array.from($('building').options).some(o=>o.value===c.building);}
 try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(Array.isArray(saved)){courses=saved.filter(valid).slice(0,50);$('saveClasses').checked=true;}}catch{}
 function persist(){try{if($('saveClasses').checked)localStorage.setItem(key,JSON.stringify(courses));else localStorage.removeItem(key);}catch{$('classStatus').textContent=t('浏览器存储不可用，课程仅保留在当前页面。','Storage unavailable; entries remain in this page only.');}}
 function line(title,text){const p=document.createElement('p'),b=document.createElement('b');b.textContent=title+' ';p.append(b,document.createTextNode(text));return p;}
 function journey(){const out=$('classJourney');out.replaceChildren();const c=courses.find(c=>c.id===selected);if(!c){out.textContent=t('选择一节课生成衔接计划。','Select a class to connect the journey.');return;}const matches=$('building').value===c.building&&$('commuteDate').value===c.day&&$('classStart').value===c.time;out.append(line(t('课程','Class'),`${c.title} · ${c.day} ${c.time} · UK`));if(!matches){out.append(line(t('计划已变化','Plan changed'),t('通勤参数与课程不一致，请重新选择该课程。','Commute settings differ from the class. Select the class again.')));return;}const name=$('building').selectedOptions[0].textContent;out.append(line(t('1 校外通勤','1 Off-campus travel'),t('公交／火车优先；下方推荐仍基于模拟时长及班次，尚不能保证赶上课程。','Bus/train preferred. Recommendations below still use simulated durations and services; arrival is not guaranteed.')),line(t('2 校园到达','2 Campus arrival'),$('campusStart')?$('campusStart').selectedOptions[0].textContent:t('选择车站或校门','Choose a station or gate')),line(t('3 目标建筑','3 Building'),name),line(t('4 楼层与教室','4 Floor and room'),(c.floor||t('楼层未知','Floor unknown'))+' · '+(c.room||t('教室未填写','Room not supplied'))),line(t('用户备注（未核验）','User notes (unverified)'),c.notes||t('尚无备注','No notes')),line(t('室内导航状态','Indoor navigation status'),t('未连接楼层图或房间目录；不会根据编号推断楼层。请核对课表、门牌或向现场工作人员确认。','No floor plans or room directory connected. Room numbers are not used to infer floors. Check the timetable, signs or staff.')));const anchor=document.createElement('a');anchor.href='#map';anchor.textContent=t('定位建筑并选择校园步行起点 →','Locate building and select campus walking origin →');anchor.style.color='#d9f36f';out.append(anchor);}
 function apply(c){selected=c.id;$('building').value=c.building;$('classStart').value=c.time;$('commuteDate').value=c.day;['building','classStart','commuteDate'].forEach(id=>$(id).dispatchEvent(new Event('change')));$('commute').requestSubmit();journey();$('classStatus').textContent=t('已把课程地点、日期和时间同步到通勤与天气查询。','Class location, date and time applied to commute and weather inputs.');}
 function render(){const list=$('classList');list.replaceChildren();courses.sort((a,b)=>(a.day+a.time).localeCompare(b.day+b.time));courses.forEach(c=>{const card=document.createElement('article');card.style.cssText='padding:12px 0;border-bottom:1px solid #ddd';card.append(line(c.title,`${c.day} ${c.time} · ${c.building} · ${c.room||'—'}`));const use=document.createElement('button');use.type='button';use.className='outline';use.textContent=t('规划去这节课','Plan this class');use.onclick=()=>apply(c);const del=document.createElement('button');del.type='button';del.className='ghost';del.textContent=t('移除','Remove');del.onclick=()=>{courses=courses.filter(x=>x.id!==c.id);persist();render();journey();};card.append(use,del);list.append(card);});if(!courses.length)list.textContent=t('尚无课程，添加课程后开始。','No classes yet. Add a class to begin.');}
 $('classForm').onsubmit=e=>{e.preventDefault();if(courses.length>=50){$('classStatus').textContent=t('最多保存50节课。','Maximum 50 classes.');return;}const c={id:crypto.randomUUID(),title:$('courseTitle').value.trim(),day:$('courseDay').value,time:$('courseTime').value,building:$('courseBuilding').value,room:$('courseRoom').value.trim(),floor:$('courseFloor').value.trim(),notes:$('courseNotes').value.trim()};if(!c.title||!valid(c))return;courses.push(c);persist();render();apply(c);};$('saveClasses').onchange=persist;
 $('sampleClass').onclick=()=>{const c={id:crypto.randomUUID(),title:t('虚构示例：HCI seminar','Fictional sample: HCI seminar'),day:$('commuteDate').value,time:'10:00',building:'R16',room:'',floor:'',notes:''};courses.push(c);persist();render();apply(c);};$('clearClasses').onclick=()=>{courses=[];selected=null;try{localStorage.removeItem(key);}catch{}$('saveClasses').checked=false;render();journey();};['building','commuteDate','classStart','campusStart','campusDestination'].forEach(id=>$(id)?.addEventListener('change',journey));render();journey();
 const style=document.createElement('style');style.textContent='[hidden]{display:none!important}#classJourney p{position:relative;z-index:1;line-height:1.7}#classes textarea{box-sizing:border-box;border:1px solid #ccc;border-radius:6px;padding:10px}';document.head.append(style);
})();
